  Ciphertext t4 = t2s + t2s - one;     // level 3

  Ciphertext u = t2 * c6;              // level 3
  Ciphertext inner = u + u + c4;       // level 3
  Ciphertext prod = t4 * inner;        // level 4

  Ciphertext term2 = t2 * c2;          // level 3
